function Get-Sha([byte[]]$b){$h=[Security.Cryptography.SHA256]::Create();try{-join($h.ComputeHash($b)|%{$_.ToString('x2')})}finally{$h.Dispose()}}
function Lock([string]$p,[ValidateSet('utf8_text','binary')][string]$contentType){$s=[IO.File]::Open([IO.Path]::GetFullPath($p),[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);try{$m=New-Object IO.MemoryStream;try{$s.CopyTo($m);$b=$m.ToArray()}finally{$m.Dispose()};$record=[ordered]@{stream=$s;sha256=(Get-Sha $b);content_type=$contentType};if($contentType-eq'utf8_text'){$t=[Text.UTF8Encoding]::new($false,$true).GetString($b);if($t.Length-and$t[0]-eq[char]0xfeff){$t=$t.Substring(1)};$record.text=$t};[pscustomobject]$record}catch{$s.Dispose();throw}}
function Life([hashtable]$e){$e.timestamp=(Get-Date).ToString('o');$b=[Text.UTF8Encoding]::new($false).GetBytes(($e|ConvertTo-Json -Compress)+[Environment]::NewLine);$s=[IO.File]::Open($lifecycle,[IO.FileMode]::Append,[IO.FileAccess]::Write,[IO.FileShare]::Read);try{$s.Write($b,0,$b.Length);$s.Flush($true)}finally{$s.Dispose()}}
function Wait-SupervisorHandshake {$deadline=(Get-Date).AddSeconds(180);do{if(Test-Path -LiteralPath $workloadLifecycle){$events=@(Get-Content -LiteralPath $workloadLifecycle -ErrorAction SilentlyContinue|%{if($_){try{$_|ConvertFrom-Json -ErrorAction Stop}catch{}}}|?{$_.event-eq'supervisor_started'-and$_.task_name-eq$taskName-and$_.canonical_gate_sha256-eq$gateShaScalar-and$_.user_confirmation_sha256-eq$confirmationShaScalar});if($events.Count-eq1){return $events[0]};if($events.Count-gt1){throw 'r16 supervisor handshake was duplicated'}};$current=$folder.GetTask($taskName);if([int]$current.State-ne4){$result=[int]$current.LastTaskResult;if($result-ne0-and$result-ne267009){$u=[uint32]([int64]$result-band0xffffffffL);throw "Task Scheduler action exited before supervisor handshake: 0x$('{0:X8}'-f$u)"};throw 'Task Scheduler action stopped before supervisor handshake'};Start-Sleep -Milliseconds 250}while((Get-Date)-lt$deadline);throw 'Task Scheduler COM supervisor did not publish its bound handshake'}
function Assert-TaskDefinition([object]$Definition,[string]$ExpectedArguments,[string]$ExpectedWorkingDirectory){
