 if([int]$Definition.Settings.MultipleInstances-ne2-or[int]$Definition.Settings.RestartCount-ne0-or$Definition.Settings.ExecutionTimeLimit-ne'PT0S'){throw 'TaskDefinition scheduler policy mismatch'}
 if(@($xml.Task.Triggers.ChildNodes|?{$_.NodeType-eq[Xml.XmlNodeType]::Element}).Count-ne0-or($xml.Task.Settings.AllowDemandStart-and$xml.Task.Settings.AllowDemandStart-ne'true')-or($xml.Task.Settings.MultipleInstances-and$xml.Task.Settings.MultipleInstances-ne'IgnoreNew')-or($xml.Task.Settings.RestartCount-and$xml.Task.Settings.RestartCount-ne'0')-or$xml.Task.Settings.ExecutionTimeLimit-ne'PT0S'){throw 'TaskDefinition XML policy mismatch'}
 if($Definition.Principal.LogonType-ne3-or[string]::IsNullOrWhiteSpace([string]$Definition.Principal.UserId)-or$Definition.Actions.Count-ne1){throw 'TaskDefinition principal or action mismatch'}
 $taskAction=$Definition.Actions.Item(1);$expectedPowerShell="$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe"
 if([string]$taskAction.Path-cne$expectedPowerShell-or[string]$taskAction.Arguments-cne$ExpectedArguments-or-not([IO.Path]::GetFullPath([string]$taskAction.WorkingDirectory).Equals([IO.Path]::GetFullPath($ExpectedWorkingDirectory),[StringComparison]::OrdinalIgnoreCase))){throw 'TaskDefinition action binding mismatch'}
}
try {
 $g=Lock $gatePath 'utf8_text';$c=Lock $confirmationPath 'utf8_text';$held+=@($g.stream,$c.stream);$gateShaScalar=[string]$g.sha256;$confirmationShaScalar=[string]$c.sha256;if($gateShaScalar-ne$ExpectedCanonicalGateSha256.ToLowerInvariant()-or$confirmationShaScalar-ne$ExpectedUserConfirmationSha256.ToLowerInvariant()){throw 'Operator-supplied SHA mismatch'};if($gateShaScalar-notmatch'^[0-9a-f]{64}$'-or$confirmationShaScalar-notmatch'^[0-9a-f]{64}$'){throw 'Locked r16 trust anchor is not a scalar SHA-256'};$gate=$g.text|ConvertFrom-Json;$confirm=$c.text|ConvertFrom-Json
 if($gate.status-ne'pass'-or$gate.fresh_launch_authorized-ne$true-or$gate.run_id_prefix-ne$prefix-or(@($gate.seeds)-join'|')-ne($seeds-join'|')-or(@($gate.expected_children)-join'|')-ne($children-join'|')){throw 'Canonical r16 gate identity failed'}
 $expectedPaths=@{dispatcher_ps1=[IO.Path]::GetFullPath($PSCommandPath);supervisor_ps1=$supervisorPath;supervisor_template_ps1=$supervisorTemplatePath;runner_sh=$runnerPath;foreground_wrapper_sh=$wrapperPath;r16_exactly_once_helpers_ps1=$helperPath;r16_native_probe_cs=$nativeSourcePath;r16_native_probe_dll=$nativeAssemblyPath;cache_manifest_json=$cacheManifestPath;cache_validator_log=$cacheValidatorPath};$bindings=@{}
 foreach($b in @($gate.source_bindings)){$name=[string]$b.name;$path=[IO.Path]::GetFullPath([string]$b.path);$contentType=[string]$b.content_type;$expectedContentType=if($name-eq'r16_native_probe_dll'){'binary'}else{'utf8_text'};if($bindings.ContainsKey($name)-or[string]$b.sha256-notmatch'^[0-9a-f]{64}$'-or$contentType-ne$expectedContentType){throw "Invalid source binding: $name"};if($expectedPaths.ContainsKey($name)-and-not$path.Equals([string]$expectedPaths[$name],[StringComparison]::OrdinalIgnoreCase)){throw "Source binding path mismatch: $name"};$l=Lock $path $contentType;if($l.sha256-ne[string]$b.sha256){$l.stream.Dispose();throw "Source binding changed: $name"};$held+=$l.stream;$bindings[$name]=$l};foreach($n in $expectedPaths.Keys){if(!$bindings.ContainsKey($n)){throw "Required source binding absent: $n"}}
 $confirmationBindings=@{};foreach($p in $confirm.source_sha256.PSObject.Properties){if($confirmationBindings.ContainsKey($p.Name)-or[string]$p.Value-notmatch'^[0-9a-f]{64}$'){throw 'Invalid confirmation source binding'};$confirmationBindings[$p.Name]=[string]$p.Value};if($confirmationBindings.Count-ne$bindings.Count){throw 'Confirmation source binding closure is incomplete'};foreach($name in $bindings.Keys){if(!$confirmationBindings.ContainsKey($name)-or$bindings[$name].sha256-ne$confirmationBindings[$name]){throw "Confirmation source binding failed: $name"}}
 . $helperPath
 Assert-R16DelegatedAuthorization $confirm $prefix $seeds $children $gateShaScalar $dispatch (Join-Path $logs "$prefix.launch.lock")|Out-Null
