 $svc=New-Object -ComObject 'Schedule.Service';$svc.Connect();$folder=$svc.GetFolder('\');if(@($folder.GetTasks(1)|?{$_.Name-match'^SleepStagePaper-r16-COM-'})){throw 'r16 Task Scheduler namespace collision'};$wslCollision=Invoke-R16BoundedWslScript "pgrep -af '[p]aper_faithful.training.cli (pilot|multi-seed-pilot)' || true" 45 'dispatcher-training-collision';if(-not[string]::IsNullOrWhiteSpace([string]$wslCollision.stdout)){throw 'WSL training process collision'};$power=Get-R16NativePowerStatus;if($power.unknown-or-not$power.power_online-or$power.critical-or$power.battery_percent-lt5){throw 'Native power gate failed'};$nvidia=(Get-Command nvidia-smi.exe -ErrorAction Stop).Source;$gpuProbe=Invoke-R16BoundedProcess $nvidia @('--query-gpu=name,driver_version','--format=csv,noheader') 30 'dispatcher-windows-gpu';if($gpuProbe.exit_code-ne0){throw 'Windows nvidia-smi gate failed'};$gpuLine=@($gpuProbe.stdout-split'\r?\n'|?{-not[string]::IsNullOrWhiteSpace($_)})|Select-Object -First 1;if(!$gpuLine-or$gpuLine-notmatch'^(?<name>.+?),\s*(?<driver>[0-9.]+)\s*$'-or$Matches.name-ne[string]$gate.gpu_gate.name-or$Matches.driver-ne[string]$gate.gpu_gate.nvidia_smi_driver_version){throw 'Windows GPU identity/driver gate failed'};$wslGpu=Invoke-R16BoundedWslScript "nvidia-smi -L >/dev/null" 45 'dispatcher-wsl-gpu';if($wslGpu.exit_code-ne0){throw 'WSL GPU gate failed'};if((Get-PSDrive C).Free/1GB-lt[double]$gate.storage_gate.c_minimum_gib-or(Get-PSDrive E).Free/1GB-lt[double]$gate.storage_gate.e_minimum_gib){throw 'Storage gate failed'}
 if($bindings.supervisor_ps1.sha256-ne$bindings.supervisor_template_ps1.sha256){throw 'r16 staged supervisor is not byte-identical to its template'};$args=New-R16SupervisorActionArguments $supervisorPath $gateShaScalar $confirmationShaScalar $taskName;$actionWorkingDirectory=Split-Path -Parent $supervisorPath;$def=$svc.NewTask(0);$def.RegistrationInfo.Description='r16 one-shot production supervisor';$def.Principal.UserId=[Security.Principal.WindowsIdentity]::GetCurrent().Name;$def.Principal.LogonType=3;$def.Settings.MultipleInstances=2;$def.Settings.RestartCount=0;$def.Settings.ExecutionTimeLimit='PT0S';$def.Settings.AllowDemandStart=$true;$action=$def.Actions.Create(0);$action.Path="$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe";$action.Arguments=$args;$action.WorkingDirectory=$actionWorkingDirectory;Assert-R16SupervisorActionArguments $args $supervisorPath $gateShaScalar $confirmationShaScalar $taskName|Out-Null;Assert-TaskDefinition $def $args $actionWorkingDirectory
 Assert-R16GpuComputeIdle 'dispatcher-pre-dispatch'
 New-Item -ItemType Directory -Path $logs -Force|Out-Null;Assert-R16OwnedLifecycleAvailable $lifecycle $dispatch 'dispatch';$marker=Open-R16PermanentMarker $dispatch 'dispatch';Life @{event='dispatch_created';run_id_prefix=$prefix;task_name=$taskName;canonical_gate_sha256=$gateShaScalar;user_confirmation_sha256=$confirmationShaScalar;task_action_arguments_length=$args.Length};$task=$folder.RegisterTaskDefinition($taskName,$def,2,$null,$null,3,$null);$running=$task.RunEx($null,0,0,$null);Life @{event='scheduler_runex_requested';run_id_prefix=$prefix;task_name=$taskName;instance_guid=[string]$running.InstanceGuid};$handshake=Wait-SupervisorHandshake;Life @{event='supervisor_handshake_validated';run_id_prefix=$prefix;task_name=$taskName;supervisor_pid=[int]$handshake.supervisor_pid};[IO.File]::WriteAllText($evidence,(@{status='dispatched';run_id_prefix=$prefix;task_name=$taskName;supervisor_pid=[int]$handshake.supervisor_pid;canonical_gate_sha256=$gateShaScalar;user_confirmation_sha256=$confirmationShaScalar;task_action_arguments_length=$args.Length;scheduler_state_authoritative=$false;authoritative_evidence=@($preflightLifecycle,$lifecycle,$workloadLifecycle,(Join-Path $logs "$prefix.workload-exit-code.txt"));timestamp=(Get-Date).ToString('o')}|ConvertTo-Json -Compress),[Text.UTF8Encoding]::new($false));exit 0
